<div class="mb-6"><p class="text-sm font-medium text-blue-600">Asistencia</p><h1 class="text-2xl font-bold">Jornadas y dispositivos</h1><p class="mt-1 text-sm text-slate-500">Registre los dos teléfonos Android como dispositivos de control.</p></div><section class="grid gap-5 lg:grid-cols-2"><article class="rounded-2xl border bg-white p-5 shadow-sm"><h2 class="font-semibold">Nueva jornada</h2><form method="post" action="index.php?url=asistencia_configurar" class="mt-4 grid gap-3 sm:grid-cols-2"><?= campoCsrf() ?><input type="hidden" name="entidad" value="jornada"><label class="form-label sm:col-span-2">Nombre<input required name="nombre" class="form-input"></label><label class="form-label">Aplica a<select name="aplica_a" class="form-input"><option>ALUMNO</option><option>DOCENTE</option><option>ADMINISTRATIVO</option></select></label><label class="form-label">Tolerancia (min.)<input required type="number" min="0" name="tolerancia_minutos" value="10" class="form-input"></label><label class="form-label">Entrada<input required type="time" name="hora_entrada" class="form-input"></label><label class="form-label">Salida<input required type="time" name="hora_salida" class="form-input"></label><label class="flex items-center gap-2 text-sm"><input type="checkbox" name="requiere_salida" checked> Requiere salida</label><button class="rounded-xl bg-blue-600 px-4 py-2 text-sm font-semibold text-white">Guardar jornada</button></form><div class="mt-5 space-y-2"><?php foreach($jornadas as $j): ?><div class="rounded-xl bg-slate-50 p-3 text-sm"><strong><?= htmlspecialchars($j['nombre']) ?></strong><span class="block text-xs text-slate-500"><?= htmlspecialchars($j['aplica_a'].' · '.$j['hora_entrada'].' - '.$j['hora_salida'].' · tolerancia '.$j['tolerancia_minutos'].' min.') ?></span></div><?php endforeach; ?></div></article><article class="rounded-2xl border bg-white p-5 shadow-sm"><h2 class="font-semibold">Nuevo dispositivo Android</h2><form method="post" action="index.php?url=asistencia_configurar" class="mt-4 space-y-3"><?= campoCsrf() ?><input type="hidden" name="entidad" value="dispositivo"><label class="form-label">Nombre<input required name="nombre" placeholder="Celular portería" class="form-input"></label><label class="form-label">Código único<input required name="codigo" placeholder="PORTERIA-01" class="form-input"></label><label class="form-label">Punto de control<input required name="punto_control" placeholder="Ingreso principal" class="form-input"></label><button class="rounded-xl bg-blue-600 px-4 py-2 text-sm font-semibold text-white">Registrar dispositivo</button></form><div class="mt-5 space-y-2"><?php foreach($dispositivos as $d): ?><div class="rounded-xl bg-slate-50 p-3 text-sm"><strong><?= htmlspecialchars($d['nombre']) ?></strong><span class="block text-xs text-slate-500"><?= htmlspecialchars($d['codigo'].' · '.$d['punto_control']) ?></span></div><?php endforeach; ?></div></article></section>
